const bank=[
  {stem:'If I were you, I _____ take a short break.',options:['will','can','may','would'],answer:3,explanation:'If I were you 表示与现在事实相反的假设，主句用 would + 动词原形。'},
  {stem:'She has lived in this city _____ 2020.',options:['for','since','during','until'],answer:1,explanation:'since 后接具体时间点；2020 是时间点。'},
  {stem:'This is the book _____ I told you about.',options:['who','where','when','that'],answer:3,explanation:'先行词 book 指物，此处可用 that 引导定语从句。'},
  {stem:'I have studied English _____ three years.',options:['since','for','at','on'],answer:1,explanation:'for 后接一段时间，three years 是时间段。'},
  {stem:'He _____ to school yesterday.',options:['go','goes','went','going'],answer:2,explanation:'yesterday 表示过去时间，动词使用过去式 went。'},
  {stem:'There _____ many books on the desk.',options:['is','are','was','be'],answer:1,explanation:'many books 是复数，there be 结构此处使用 are。'}
];
const $=selector=>document.querySelector(selector),letters=['A','B','C','D'];let position=0,selected=null,submitted=false,correct=0,answered=0;const dateKey=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
function render(){const q=bank[position%bank.length];$('#number').textContent=String(position+1).padStart(2,'0');$('#stem').textContent=q.stem;$('#options').innerHTML=q.options.map((option,i)=>'<label class="option"><input type="radio" name="answer" value="'+i+'" '+(selected===i?'checked':'')+(submitted?' disabled':'')+'><span class="letter">'+letters[i]+'</span><span>'+option+'</span></label>').join('');$('#options').querySelectorAll('input').forEach(input=>input.onchange=()=>{selected=Number(input.value);$('#confirmAnswer').disabled=false});$('#confirmAnswer').hidden=submitted;$('#confirmAnswer').disabled=selected===null;$('#nextQuestion').hidden=!submitted;$('#resultPanel').hidden=!submitted;$('#infiniteStats').textContent='已完成 '+answered+' 题'+(answered?' · 正确率 '+Math.round(correct/answered*100)+'%':'')}
function moveNext(){position++;selected=null;submitted=false;render()}
$('#confirmAnswer').onclick=()=>{if(selected===null||submitted)return;submitted=true;answered++;const q=bank[position%bank.length],right=selected===q.answer;if(right)correct++;const storageKey='advance-infinite-'+dateKey(),old=JSON.parse(localStorage.getItem(storageKey)||'{"answered":0,"correct":0}');localStorage.setItem(storageKey,JSON.stringify({answered:old.answered+1,correct:old.correct+(right?1:0)}));$('#resultPanel').innerHTML='<strong class="'+(right?'correct':'incorrect')+'">'+(right?'回答正确':'回答有误')+'</strong><p>正确答案：'+letters[q.answer]+' · '+q.options[q.answer]+'</p><p>'+q.explanation+'</p>';render()};$('#nextQuestion').onclick=moveNext;$('#skip').onclick=moveNext;$('#back').onclick=()=>location.href='index.html?view=home';render();
